{
  "headline": "FDA's records trace our supply to a plant classified OAI 694 days before the shortage posting",
  "headline_cites": ["D3"],
  "sentences": [
    {
      "text": "FDA first posted the lorazepam injection shortage on 2018-05-03 and it remains current as of 2026-10-21.",
      "cites": ["E35", "E31"]
    },
    {
      "text": "The label for NDC 00409-1985-30 names Hospira, Inc. (FEI 1925262) as the manufacturing plant.",
      "cites": ["E18"]
    },
    {
      "text": "FDA inspection 976095 at that plant ended 2016-06-08 and was classified OAI, 694 days before the shortage posting.",
      "cites": ["E12", "D3"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2017-02-14, 443 days before the posting.",
      "cites": ["E17", "D5"]
    },
    {
      "text": "A later inspection 1064827 ended 2018-08-15 and was also classified OAI, with the classification letter dated 2020-04-22.",
      "cites": ["E14", "D9"]
    },
    {
      "text": "Hospira's FDA shortage entry shows limited supply available with next delivery June 2027 and estimated recovery December 2027.",
      "cites": ["E34"]
    },
    {
      "text": "The rule-identified best option is to buy from Civica, Inc., which is not on FDA's shortage list today.",
      "cites": ["D12"]
    }
  ]
}
